(function census() {
  const app = window.__CITY_APP, C = window.CITY;
  const tri = (g) => (g.index ? g.index.count : g.attributes.position.count) / 3;
  const kinds = {};
  app.scene.traverse((o) => {
    if (!o.isMesh || !o.castShadow) return;
    const per = tri(o.geometry), n = o.isInstancedMesh ? o.count : 1;
    const k = (o.name || '?') + '|' + (o.material.name || o.material.type) + '|' + per;
    const e = kinds[k] || (kinds[k] = { meshes: 0, instances: 0, tris: 0 });
    e.meshes++; e.instances += n; e.tris += per * n;
  });
  const top = Object.entries(kinds).sort((a, b) => b[1].tris - a[1].tris).slice(0, 40);
  const res = { q: location.search, quality: C.QUALITY.name || C.QUALITY.tier || null, cullingStats: app.cullingStats, poleStats: C.poleStats && { placed: C.poleStats.placed, fallback: C.poleStats.fallback }, casters: Object.fromEntries(top) };
  console.log('[ride-check] census ' + JSON.stringify({ cullingStats: res.cullingStats, poleStats: res.poleStats }));
  return res;
})()

(function tally() {
  return new Promise((resolve) => {
    const app = window.__CITY_APP, r = app.renderer, b = r.backend, sh = app.lightingSystem.sunLight.shadow;
    const cams = new Map();
    const n = typeof sh.getViewportCount === 'function' ? sh.getViewportCount() : 2;
    for (let i = 0; i < n; i++) cams.set(sh.getCamera(i), i);
    const t = { shadow: [0, 1].map(() => ({ passes: new Set(), tris: 0, draws: 0 })), view: { frames: new Set(), tris: 0, draws: 0 }, byKind: {}, people: {} };
    const tri = (g) => (g.index ? g.index.count : g.attributes.position.count) / 3;
    const orig = b.draw;
    b.draw = function (ro, info) {
      const before = info.render.triangles;
      const res = orig.apply(this, arguments);
      const d = info.render.triangles - before;
      const o = ro.object, ci = cams.get(ro.camera);
      if (ci !== undefined) {
        const s = t.shadow[ci];
        s.passes.add(r.info.frame); s.tris += d; s.draws++;
        const k = (o.name || '?') + '|' + (o.material.name || o.material.type) + '|' + tri(o.geometry);
        t.byKind[k] = (t.byKind[k] || 0) + d;
      } else {
        t.view.frames.add(r.info.frame); t.view.tris += d; t.view.draws++;
      }
      if (/^People/.test(o.name)) {
        const p = t.people[o.name + (ci !== undefined ? ':shadow' : ':view')] ||= { draws: 0, tris: 0 };
        p.draws++; p.tris += d;
      }
      return res;
    };
    let frames = 0;
    const tick = () => {
      if (++frames < 40) return requestAnimationFrame(tick);
      b.draw = orig;
      const per = (x, k) => Math.round(x / Math.max(1, k));
      const out = {
        q: location.search,
        shadowPasses: t.shadow.map((s) => s.passes.size),
        shadowTrisPerPass: t.shadow.map((s) => per(s.tris, s.passes.size)),
        shadowDrawsPerPass: t.shadow.map((s) => per(s.draws, s.passes.size)),
        viewFrames: t.view.frames.size,
        viewTrisPerFrame: per(t.view.tris, t.view.frames.size),
        viewDrawsPerFrame: per(t.view.draws, t.view.frames.size),
        shadowByKindPerPass: Object.fromEntries(Object.entries(t.byKind).sort((a, b) => b[1] - a[1]).slice(0, 25)
          .map(([k, v]) => [k, per(v, t.shadow[0].passes.size + t.shadow[1].passes.size)])),
        people: Object.fromEntries(Object.entries(t.people).map(([k, v]) => [k, { drawsPerFrame: +(v.draws / Math.max(1, t.view.frames.size)).toFixed(2), trisPerFrame: per(v.tris, t.view.frames.size) }])),
        peds: app.trafficSystem && app.trafficSystem.stats ? app.trafficSystem.stats : undefined
      };
      console.log('[ride-check] tally ' + JSON.stringify({ shadowTrisPerPass: out.shadowTrisPerPass, viewTrisPerFrame: out.viewTrisPerFrame, people: out.people }));
      resolve(out);
    };
    requestAnimationFrame(tick);
  });
})()

